#!/usr/bin/env node
/*
 * scripts/test-compare.mjs - verify the browser-side comparer against the shared
 * golden vectors.
 *
 * internal/site/shell/compare.js is the only duplicated logic in benchbook: the
 * compare page has to work from static files. It is therefore checked against the
 * exact same fixtures the Go tests use (testdata/utest_vectors.json, generated by
 * SciPy), plus a handful of known values for erfc and the classification rules.
 *
 *   node scripts/test-compare.mjs
 *
 * Exits 0 when everything matches, 1 otherwise.
 */

import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const require = createRequire(import.meta.url);
const compare = require(join(root, "internal/site/shell/compare.js"));

let failures = 0;

function check(name, actual, expected, tolerance = 0) {
  const difference = Math.abs(actual - expected);
  if (difference <= tolerance) {
    console.log(`ok   ${name} (${actual} vs ${expected})`);
    return;
  }
  console.error(`FAIL ${name}: got ${actual}, expected ${expected} (tolerance ${tolerance})`);
  failures += 1;
}

function checkEqual(name, actual, expected) {
  if (actual === expected) {
    console.log(`ok   ${name} (${actual})`);
    return;
  }
  console.error(`FAIL ${name}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`);
  failures += 1;
}

/* --- golden U-test vectors ------------------------------------------------- */

const fixtures = JSON.parse(readFileSync(join(root, "testdata/utest_vectors.json"), "utf8"));
for (const vector of fixtures.vectors) {
  const result = compare.mannWhitneyU(vector.a, vector.b);
  if (result.error) {
    console.error(`FAIL ${vector.name}: ${result.error}`);
    failures += 1;
    continue;
  }
  check(`${vector.name} [p]`, result.p, vector.p, fixtures.tolerance);
  check(`${vector.name} [u]`, result.u, vector.u, 0);
  checkEqual(`${vector.name} [method]`, result.method, vector.method);
}

/* --- normal CDF sanity ----------------------------------------------------- */

const erfCases = [
  [0, 0],
  [1, 0.8427007929497149],
  [2, 0.9953222650189527],
  [3, 0.9999779095030014]
];
for (const [x, expected] of erfCases) {
  /* erfc(x) = 1 - erf(x); compare at machine precision. */
  check(`erfc(${x})`, compare.erfc(x), 1 - expected, 1e-12);
}

/* --- classification rules -------------------------------------------------- */

const options = {
  alpha: compare.constants.defaultAlpha,
  minEffectPct: compare.constants.defaultMinEffectPct,
  minSamples: compare.constants.defaultMinSamples
};

function samples(nsValues, extra) {
  return nsValues.map((value, index) => {
    const sample = { iterations: 1000 + index, ns_op: value, bytes_op: 1024, allocs_op: 16, extra: {} };
    if (extra) {
      for (const [unit, values] of Object.entries(extra)) {
        sample.extra[unit] = values[index];
      }
    }
    return sample;
  });
}

const faster = samples([15100, 15210, 15050, 15180, 15240, 15090, 15160, 15220]);
const slower = samples([12400, 12510, 12380, 12480, 12530, 12420, 12460, 12500]);

/* lower ns/op is better: from slow -> to fast must be "improved". */
const improvement = compare.evaluate(faster, slower, "ns_op", options);
checkEqual("ns_op improvement", improvement.classification, compare.classes.improved);

/* The same numbers in the other direction must be a regression. */
const regression = compare.evaluate(slower, faster, "ns_op", options);
checkEqual("ns_op regression", regression.classification, compare.classes.regressed);

/* Throughput: higher is better, so a bigger MB/s must be an improvement. */
function throughputSamples(values) {
  return values.map((value, index) => ({
    iterations: 1000 + index,
    ns_op: 1000,
    bytes_op: 0,
    allocs_op: 0,
    extra: { "MB/s": value }
  }));
}

const throughput = compare.evaluate(
  throughputSamples([500, 505, 498, 502, 501, 503, 499, 504]),
  throughputSamples([700, 705, 698, 702, 701, 703, 699, 704]),
  "MB/s",
  options
);
checkEqual("MB/s improvement", throughput.classification, compare.classes.improved);
checkEqual("MB/s higher-is-better", compare.isHigherBetter("MB/s"), true);
checkEqual("ns_op lower-is-better", compare.isHigherBetter("ns_op"), false);

/* Fewer than four samples per side can never be significant. */
const tiny = compare.mannWhitneyU([1, 2, 3], [4, 5, 6]);
checkEqual("three samples per side is insufficient", typeof tiny.error === "string", true);

/* Zero baseline: the ratio is undefined, the absolute change is what matters. */
const zeroFrom = samples([1000, 1010, 990, 1005, 1002, 998, 1004, 1001]).map((sample) => {
  sample.allocs_op = 0;
  return sample;
});
const zeroTo = samples([1000, 1010, 990, 1005, 1002, 998, 1004, 1001]).map((sample) => {
  sample.allocs_op = 3;
  return sample;
});
const zeroBaseline = compare.evaluate(zeroFrom, zeroTo, "allocs_op", options);
checkEqual("zero baseline delta undefined", zeroBaseline.deltaDefined, false);
checkEqual("zero baseline still classified", zeroBaseline.classification, compare.classes.regressed);

if (failures > 0) {
  console.error(`\n${failures} check(s) failed`);
  process.exit(1);
}
console.log("\nall compare.js checks passed");
